import { fileURLToPath } from 'node:url';
import { buildLegacySitemapUrls } from './sitemap/build-urls';

// Opt-in HTTPS dev server (set by `make dev-tls`). Certs are generated by
// `make certs` via mkcert; see Makefile for the one-time setup.
const devTls = process.env.NUXT_DEV_TLS === '1';

const baseURL = 'https://revue-de-presse.org';
const description =
  'Chaque jour, une revue de presse des 10 publications des médias les plus marquantes';
const title = 'Revue de presse - revue-de-presse.org';
const banner = `${baseURL}/revue-de-presse-banner.jpg`;
const icon = '/logo-revue-de-presse.png';

export default defineNuxtConfig({
  compatibilityDate: '2025-01-01',
  devtools: { enabled: true },
  ssr: true,

  // In plain dev, bind to 127.0.0.1 (not localhost) so the browser origin
  // matches the loopback redirect_uri baked into the atproto OAuth client
  // (`http://127.0.0.1:3000/...` — see server/utils/blueskyOauth.ts).
  // Under NUXT_DEV_TLS=1, serve over HTTPS on local.revue-de-presse.org
  // instead (mkcert-issued certs; that host also resolves to 127.0.0.1).
  devServer: devTls
    ? {
        host: 'local.revue-de-presse.org',
        port: 3000,
        https: {
          key: './.certs/local-key.pem',
          cert: './.certs/local-cert.pem',
        },
      }
    : {
        host: '127.0.0.1',
        port: 3000,
      },

  runtimeConfig: {
    apiBaseUrl: '',
    apiClientSecret: '',
    // Chat / Bluesky OAuth — server-only.
    // Defaults are read from .env.local at build/boot time so operators
    // only deal with one env var name per concern (no NUXT_CHAT_… prefix
    // gymnastics). Production / Netlify also set the same names directly.
    chat: {
      // 256-bit shared secret minted by `make chat-jwt-secret` in the
      // org.revue-de-presse.api repo. The SAME value lives in:
      //   1. org.revue-de-presse.api/.env.local     (API verifier)
      //   2. org.revue-de-presse.benchmark/nuxt/.env.local (Nuxt signer)
      //   3. Netlify env vars                       (Nuxt signer, prod)
      apiJwtSecret: process.env.API_JWT_SECRET ?? '',
      // Public site origin (no trailing slash). Empty in dev → server
      // falls back to a localhost loopback client_id.
      publicOrigin: process.env.PUBLIC_ORIGIN ?? '',
      // Where to keep session + OAuth state on disk in dev.
      sessionStoreDir: process.env.CHAT_SESSION_STORE_DIR ?? './.session-store',
    },
  },

  experimental: {
    appManifest: false,
  },

  // Pre-compress public assets at build time so Nitro can serve .gz/.br
  // variants to clients that accept them. Without this, the preview server
  // sends raw bundles and Lighthouse flags `uses-text-compression`
  // (≈276 KiB of savings on the home route).
  nitro: {
    compressPublicAssets: { gzip: true, brotli: true },
  },

  alias: {
    '@design-system': fileURLToPath(new URL('../design-system/output/vue/src', import.meta.url)),
    '@design-system-css': fileURLToPath(new URL('../design-system/output/components.css', import.meta.url)),
    '@tokens': fileURLToPath(new URL('../design-system/src/tokens', import.meta.url)),
    '@icons': fileURLToPath(new URL('../design-system/src/icons', import.meta.url)),
  },

  // tokens.css is the design-system's foundation (vars). components.css
  // is the per-component CSS we strip from the Mitosis-emitted Vue files
  // (see design-system/scripts/post-mitosis.mjs) to avoid Vue SSR hydration
  // warnings.
  css: ['@tokens/tokens.css', '@design-system-css'],

  vite: {
    server: {
      fs: {
        allow: [fileURLToPath(new URL('..', import.meta.url))],
      },
    },
  },

  router: {
    options: {
      strict: true,
    },
  },

  modules: ['nuxt-module-feed', '@nuxtjs/sitemap'],

  feed: {
    sources: [
      {
        path: '/feed.xml',
        type: 'rss2',
        cacheTime: 60 * 15, // 15 min, parity with legacy 1000 * 60 * 15
      },
    ],
  },

  site: {
    url: baseURL,
    name: 'revue-de-presse.org',
  },

  sitemap: {
    // Suppress raw ':day' / ':twitterId' placeholders from auto-discovery and
    // the 404 page; concrete dated URLs come from urls() below.
    exclude: ['/contenu-introuvable', '/source/**', '/[day]', '/[day]/**'],
    defaults: { changefreq: 'monthly', priority: 0.7 },
    urls: buildLegacySitemapUrls,
  },

  app: {
    head: {
      title,
      htmlAttrs: { lang: 'fr' },
      meta: [
        { charset: 'utf-8' },
        { name: 'viewport', content: 'width=device-width, initial-scale=1' },
        { name: 'description', content: description },
        { name: 'author', content: '@revue_2_presse' },
        { name: 'theme-color', content: '#006663' },
        { property: 'og:type', content: 'website' },
        { property: 'og:url', content: baseURL },
        { property: 'og:title', content: title },
        { property: 'og:description', content: description },
        { property: 'og:image', content: banner },
        { property: 'og:site_name', content: title },
        { name: 'twitter:card', content: 'summary_large_image' },
        { name: 'twitter:site', content: '@revue_2_presse' },
        { name: 'twitter:creator', content: '@revue_2_presse' },
        { name: 'twitter:title', content: title },
        { name: 'twitter:description', content: description },
        { name: 'twitter:image', content: banner },
        { name: 'apple-mobile-web-app-capable', content: 'yes' },
        { name: 'apple-mobile-web-app-status-bar-style', content: 'default' },
        { name: 'apple-mobile-web-app-title', content: title },
        { name: 'mobile-web-app-capable', content: 'yes' },
        { name: 'application-name', content: title },
        { name: 'msapplication-TileColor', content: '#006663' },
      ],
      link: [
        { rel: 'icon', type: 'image/svg+xml', href: '/logo-revue-de-presse.svg' },
        { rel: 'icon', type: 'image/png', href: icon },
        { rel: 'shortcut icon', href: icon },
        { rel: 'apple-touch-icon', href: '/revue-de-presse_512x512_006663.png' },
        { rel: 'manifest', href: '/manifest.webmanifest' },
        {
          rel: 'preload',
          href: '/fonts/signika-regular.woff2',
          as: 'font',
          type: 'font/woff2',
          crossorigin: '',
        },
        {
          rel: 'preload',
          href: '/fonts/roboto-regular.woff2',
          as: 'font',
          type: 'font/woff2',
          crossorigin: '',
        },
      ],
      // Noscript banner is injected via the Nitro `render:html` hook below
      // (`hooks['render:html']`). Placing it via `app.head.noscript` lands it
      // inside <head>, where the inner <div> banner is invalid HTML and the
      // parser drops it — so the fallback wouldn't render with JS disabled.
    },
  },
});
